#[test]
fn path_exists_argument_is_relative_to_submodule_working_directory() {
  Test::new()
    .justfile("mod foo")
    .write("foo/baz", "")
    .write(
      "foo/mod.just",
      "
        bar:
          @echo {{ path_exists('baz') }}
      ",
    )
    .stdout_regex("true\n")
    .args(["foo", "bar"])
    .success();
}

