#[test]
fn read() {
  Test::new()
    .justfile("foo := read('bar')")
    .write("bar", "baz")
    .args(["--evaluate", "foo"])
    .stdout("baz")
    .success();
}

#[test]
fn read_file_not_found() {
  Test::new()
    .justfile("foo := read('bar')")
    .args(["--evaluate", "foo"])
    .stderr_regex(r"error: call to function `read` failed: I/O error reading `bar`: .*")
    .failure();
}

#[test]
fn shell_with_powershell() {
  if !cfg!(windows) {
    return;
  }

  Test::new()
    .justfile(
      "
        set windows-shell := ['pwsh.exe', '-NoLogo', '-Command']

        foo := shell('Write-Output bar')

        default:
          @echo {{foo}}
      ",
    )
    .shell(false)
    .stdout("bar\r\n")
    .success();
}

#[test]
fn module_path() {
  assert_eval("module_path()", "");
}

#[test]
fn module_path_in_submodule() {
  Test::new()
    .write("foo.just", "mod bar")
    .write("bar.just", "baz := module_path()")
    .justfile("mod foo")
    .args(["--evaluate", "foo::bar::baz"])
    .stdout("foo::bar")
    .success();
}

#[test]
fn num_jobs_returns_jobs() {
  Test::new()
    .justfile(
      "
        set lists

        foo:
          @echo {{ num_jobs() }}
      ",
    )
    .unstable()
    .args(["--jobs", "9999"])
    .stdout("9999\n")
    .success();
}

#[test]
fn num_jobs_falls_back_to_empty_list() {
  Test::new()
    .justfile(
      "
        set lists

        foo:
          @echo '{{ show(num_jobs()) }}'
      ",
    )
    .unstable()
    .stdout("[]\n")
    .success();
}

#[test]
fn num_jobs_requires_lists() {
  Test::new()
    .justfile(
      "
        foo:
          @echo {{ num_jobs() }}
      ",
    )
    .stderr(
      "
        error: the `num_jobs()` function requires `set lists`
         ——▶ justfile:2:12
          │
        2 │   @echo {{ num_jobs() }}
          │            ^^^^^^^^
      ",
    )
    .failure();
}

#[test]
fn dry_run_does_not_execute_shell_function() {
  Test::new()
    .justfile(
      "
        foo:
          echo {{ shell('exit 1') }}
      ",
    )
    .arg("--dry-run")
    .stderr("echo shell(\"exit 1\")\n")
    .success();
}

#[test]
fn dry_run_shell_function_output_is_escaped() {
  Test::new()
    .justfile(
      r#"
        foo:
          echo {{ shell('exit 1', '"') }}
      "#,
    )
    .arg("--dry-run")
    .stderr(
      r#"
        echo shell("exit 1", "\"")
      "#,
    )
    .success();
}
