          │
        2 │   @echo '{{ style('hippo') }}foo{{NORMAL}}'
          │             ^^^^^
      ",
    )
    .failure();
}

#[test]
fn read() {
  Test::new()
    .justfile("foo := read('bar')")
    .write("bar", "baz")
    .args(["--evaluate", "foo"])
    .stdout("baz")
    .success();
}

#[test]
fn read_file_not_found() {
  Test::new()
    .justfile("foo := read('bar')")
    .args(["--evaluate", "foo"])
